async function query(params: QueryParams): Promise<any> {
  // Implementation details...
  return /* result */;
}

interface QueryParams {
  /** Optional source URL, file path, or identifier. */
  source?: string;
  /** Query string or expression. */
  query: string;
  /** Optional object of variable values. */
  variables?: Record<string, any>;
  /** Optional object of custom options. */
  options?: Record<string, any>;
}

